uint32_t CalculateCRC32(const uint8_t *data, size_t len)
{
    int iIndex;
    uint32_t crc = 0; // 初始化 CRC 值
    for (iIndex=0; iIndex < len; iIndex++)
    {
        crc = table[(crc ^ data[iIndex]) & 0xff] ^ (crc >> 8);
    }
    return crc;
}

// 打印二进制格式的 CRC32
void print_crc32_binary(uint32_t crc) 
{
    for (int i = 31; i >= 0; i--) {
        printf("%d", (crc >> i) & 1);
    }
    printf("\n");
}
